// A disposable deck for phone inspection. Never reads or writes a player save.
import { newState, createRun, advanceMap, getSupportChoices, getChoices, selectNode, beginFlightAttempt, markFlightAttemptStarted, finishFlight, settleCheckpoint } from './model.mjs?v=guide-clarity-1';
import { makeSkillCard, describeSkillCard } from './skill-cards.mjs?v=guide-clarity-1';
import { grantTreasureGift } from './treasure.mjs?v=guide-clarity-1';
import { cleanSlotInscriptions, writeInscription, INSCRIPTIONS } from './inscriptions.mjs?v=guide-clarity-1';
import { ROUTE_BONUSES } from './route-bonuses.mjs?v=guide-clarity-1';

export function prepareCardInspectorReward(run, cardId = 'harvest-rare', objective = 'gilded') {
  if (run.cardReward && !run.cardReward.uiAcknowledged) return;
  const id = `sample-reward:${run.cardHistory.length}`;
  run.cardReward = { id, source: 'flight', claimed: false, card: makeSkillCard(cardId, id) };
}

// A full receipt stress case, still generated by the production flight and
// settlement code. These are disposable run inputs, never invented receipt rows.
function prepareLateGamePack(state) {
  const run = state.run;
  for (let chapter = 0; chapter < 2; chapter++) {
    run.mapFlights = 6;
    run.phase = 'map-clear';
    advanceMap(run);
  }
  run.stats = { flights: 16, attempts: 18, deaths: 2, collected: 236, elites: 4, events: 5, challenges: 9 };
  run.mapFlights = 4;
  run.cardSlots = 5;
  run.cardFutureCapacity = 9;
  run.cardCruisingSpeed = 3;
  run.cardCruisingSpeedUnlocked = 3;
  run.mountedCards = ['tight-packing-iii', 'wayfarers-purse', 'growth-ring', 'wind-feather', 'edge-reach']
    .map((id, i) => makeSkillCard(id, `sample:late:mounted:${i}`));
  run.reserveCards = ['echo', 'body-spark', 'deep-vessel', 'spark-cache', 'harvest-legendary', 'closing-chord', 'twin-orbit', 'fast-spool']
    .map((id, i) => makeSkillCard(id, `sample:late:stored:${i}`));
  run.reserveCards[3].charges = 2;
  run.reserveCards[7].charges = 1;
  run.condensedGlow = 137;
  run.artifacts = ['glow-wick', 'flash-stone', 'hearth-bloom', 'echo-vessel', 'overflow-coil', 'echo-bell',
    'dawn-loom', 'sunspool', 'galespun-spindle', 'threefold-chalice', 'night-gardener', 'moonwake-lens', 'ascent-chime'];
  run.seenArtifacts = [...run.artifacts];
  run.artifactCharges = { 'glow-wick': 3, 'flash-stone': 2 };
  run.treasureGifts = { vessel: 1, wick: 1, toll: 1, seal: 1 };
  run.treasureCapacity = 10;
  run.pendingOath = { id: 'night-ledger' };

  // Follow actual connected map sites to a late ordinary round. This keeps the
  // draft, challenge, chapter and route identities consistent with a real run.
  while (run.step < run.map.length) {
    const choices = getChoices(run);
    const node = choices.find(site => site.type === 'flight' && !site.elite && site.row >= 4) || choices[0];
    selectNode(run, node.id);
    if (node.type === 'flight' && !node.elite && node.row >= 4) break;
    run.step = node.row + 1;
    run.phase = 'map';
  }
  run.current.bonusId = objective;
  beginFlightAttempt(run);
  markFlightAttemptStarted(run);
  finishFlight(run, { success: true, flame: 100, collected: 26, bodyFuelCollected: 18, collectorPickups: 8,
    condensedGlow: 18, pickupOverflow: 180,
    artifactCharges: { 'glow-wick': 0, 'flash-stone': 0 },
    artifactActivations: { 'glow-wick': 3, 'flash-stone': 2, 'hearth-bloom': 5, 'overflow-coil': 4,
      'echo-bell': 5, 'dawn-loom': 4, sunspool: 4, 'galespun-spindle': 3, 'threefold-chalice': 2,
      'night-gardener': 5, 'moonwake-lens': 3, 'ascent-chime': 4 },
    routeBonus: { id: objective, eligible: true, complete: true, target: objective === 'gilded' ? 4 : ROUTE_BONUSES[objective].target, progress: 6, packed: 18 } });
  settleCheckpoint(state);
}

/** Mock run endings for the menu audit: real flags, no save. */
function prepareEndScreen(run, kind) {
  run.stats = { flights: 18, attempts: 21, deaths: 3, collected: 312, elites: 4, events: 5, challenges: 9 };
  run.difficulty = 3;
  run.cardSlots = 5;
  run.mountedCards = ['tight-packing-iii', 'harvest-rare', 'cache-handling', 'wind-feather', 'edge-reach'].map((id, i) => makeSkillCard(id, 'sample:end:' + i));
  if (kind === 'mapclear') { run.phase = 'map-clear'; return; }
  if (kind === 'retry') { run.current = getChoices(run).find(n => n.type === 'flight'); run.lives = 2; run.phase = 'retry'; return; }
  if (kind === 'death') { run.deathPending = true; run.lives = 2; run.lastAttempt = { nodeName: 'Bell Garden', livesRemaining: 2 }; return; }
  run.phase = 'ended';
  run.success = kind === 'victory';
  if (kind === 'victory') {
    run.bossDefeated = true;
    run.winningHand = run.mountedCards.filter(Boolean);
    run.finalCardTrophy = describeSkillCard(makeSkillCard('harvest-legendary', 'sample:end:trophy'));
    run.cardFutureCapacity = 0;
    run.cardClearReceipts = [];
  } else { run.lives = 0; run.lastAttempt = { nodeName: 'Bell Garden', livesRemaining: 0 }; }
  run.endScore = Object.freeze({ v: 1, runId: run.id, earned: 482, ascension: 3, outcome: kind === 'victory' ? 'won' : 'lost', flights: 18, version: 'mock', complete: true,
    comparison: { ascensionBest: 482, overallBest: 482, ascensionNew: kind === 'victory', overallNew: kind === 'victory' } });
}
export function createCardInspectorState(params = new URLSearchParams()) {
  const state = newState();
  state.profile.tutorialComplete = true;
  state.settings.skipTutorial = true;
  state.run = createRun(state.profile, 'cards-workbench-sample', 1, { cards: true });
  const run = state.run;
  run.startingGiftId = 'card:body-spark';
  run.guideSkipped = true;
  run.mountedCards = ['echo', 'spark-cache', 'deep-vessel'].map((id, i) => makeSkillCard(id, `sample:${i}`));
  run.mountedCards[1].charges = 4;
  run.reserveCards = ['body-spark', 'spark-cache', 'harvest-rare', 'harvest-legendary', 'cache-handling', 'flash-handling'].map((id, i) => makeSkillCard(id, `sample:stored:${i}`));
  run.reserveCards[1].charges = 2;
  if (params.get('deck') === 'large') {
    for (let i = 0; i < 120; i++) run.reserveCards.push(makeSkillCard(['body-spark', 'deep-vessel', 'harvest-rare', 'harvest-legendary'][i % 4], `sample:large:${i}`));
  }
  run.condensedGlow = 90;
  if (params.get('scenario') === 'departure') {
    run.mountedCards = (params.get('chain') || 'lift-guide,rhythm,harvest-common').split(',').slice(0, 5).map((id, index) => makeSkillCard(id.trim(), `sample:departure:${index}`));
    run.cardSlots = Math.max(3, run.mountedCards.length);
    selectNode(run, getChoices(run).find(node => node.type === 'flight').id);
    return state;
  }
  if (params.get('scenario') === 'pack') {
    if (params.get('late') === '1') {
      prepareLateGamePack(state);
      return state;
    }
    const node = getChoices(run).find(n => n.type !== 'support');
    selectNode(run, node.id);
    run.current.bonusId = 'gilded';
    run.artifacts = ['flash-stone'];
    run.artifactCharges = { 'flash-stone': 2 };
    beginFlightAttempt(run);
    markFlightAttemptStarted(run);
    // ?engine=1: the engine lines of the ceremony (Pack cards, Kept by your engine) with sample amounts.
    const engineLines = params.get('engine') === '1' ? { cardPack: { sparks: 6, asked: 6, stored: 2, turns: 1 }, cardEngineStored: 2 } : {};
    finishFlight(run, { success:true, flame:50, collected:6, ...engineLines,
      artifactCharges:{'flash-stone':1}, artifactActivations:{'flash-stone':1},
      routeBonus:{id:'gilded', eligible:true, complete:true, target:4, progress:4} });
    settleCheckpoint(state);
    return state;
  }
  if (params.get('slots') === '5') {
    run.cardSlots = 5;
    run.mountedCards.push(makeSkillCard('chameleon', 'sample:3'), makeSkillCard('harvest-legendary', 'sample:4'));
  }
  // Dev only: the end-of-game screens. ?scenario=victory (You won: scorecard + final Chain recap), defeat (Game over), death (a light has fallen).
  if (['victory', 'defeat', 'death', 'mapclear', 'retry'].includes(params.get('scenario'))) prepareEndScreen(run, params.get('scenario'));
  if (params.get('scenario') === 'reward') prepareCardInspectorReward(run, params.get('reward') === 'edge-reach' ? 'edge-reach' : 'harvest-rare', params.get('objective') || 'gilded');
  // Dev only: ?scenario=event&event=5 opens that event stop (two outcomes).
  if (params.get('scenario') === 'event') {
    if (run.cardReward) run.cardReward.uiAcknowledged = true;
    const node = run.map.flat().find(n => n.kind === 'event') || run.map.flat().find(n => n.type === 'support' && n.kind !== 'camp');
    Object.assign(node, {kind: 'event', eventIndex: Number(params.get('event') || 5)});
    run.current = node; run.step = node.row; run.path = [node.id]; run.phase = 'support'; run.supportOffers = null;
    run.lives = Math.max(1, run.lives - 1);
  }
  if (params.get('scenario') === 'proximity') run.reserveCards.push(makeSkillCard('edge-reach', 'sample:edge-reach'));
  if (params.get('scenario') === 'closed-eye') {
    run.mountedCards = ['lantern-lens', 'climb', 'harvest-common'].map((id, slot) =>
      makeSkillCard(id, 'sample:closed-eye:' + slot));
    run.pendingOath = { id: 'closed-eye' };
  }
  if (params.get('scenario') === 'combos') {
    run.companions=['collector'];run.companionRole='collector';
    run.artifacts=['dawn-loom','echo-bell','wayward-seed'];
    run.mountedCards=['rhythm','harvest-common','ring-spring'].map((id,i)=>makeSkillCard(id,`sample:combo:${i}`));
    run.reserveCards=['toll-bell','echo','deep-vessel','harvest-rare'].map((id,i)=>makeSkillCard(id,`sample:stored:combo:${i}`));
  }
  if (params.get('scenario') === 'rowcraft') {
    run.companions = ['collector']; run.companionRole = 'collector';
    run.cardSlots = 5;
    run.mountedCards = ['echo', 'body-spark', 'kindling-bead', 'refrain', 'closing-chord'].map((id, i) => makeSkillCard(id, `sample:rowcraft:${i}`));
    run.reserveCards = ['use-doubler', 'ember-feeder', 'spark-cache', 'fast-spool', 'devourer', 'edge-reach'].map((id, i) => makeSkillCard(id, `sample:stored:rowcraft:${i}`));
  }
  if (params.get('scenario') === 'new-common') {
    run.cardSlots = 5;
    run.mountedCards = ['growth-ring', 'wind-feather', 'wick-doubler', 'fast-spool', 'body-spark'].map((id, i) => makeSkillCard(id, `sample:new-common:${i}`));
    run.reserveCards.push(makeSkillCard('echo', 'sample:new-common:echo'));
  }
  if (['dream', 'dream-rest'].includes(params.get('scenario'))) {
    run.mountedCards = ['dream', 'lift-guide', 'deep-vessel'].map((id, i) => makeSkillCard(id, `sample:dream:${i}`));
    const node = run.map.flat().find(n => n.kind === (params.get('scenario') === 'dream-rest' ? 'camp' : 'elite'));
    run.current = node; run.step = node.row; run.path = [node.id];
    run.phase = node.kind === 'camp' ? 'support' : 'briefing';
  }
  if (params.get('scenario') === 'rest') {
    if (run.cardReward) run.cardReward.uiAcknowledged = true;
    const node = run.map.flat().find(n => n.kind === 'camp');
    run.current = node;
    run.step = node.row;
    run.path = [node.id];
    run.phase = 'support';
    // Dev only (captures): ?stored=N Stored Sparks, ?hearts=N, ?meter=N, ?slotdone=1 (slot already added this map), ?cardslots=5.
    if (params.has('stored')) run.condensedGlow = Number(params.get('stored')) || 0;
    if (params.has('hearts')) run.lives = Number(params.get('hearts'));
    if (params.has('meter')) run.flame = Number(params.get('meter'));
    if (params.get('slotdone')) run.cardSlotMaps.push(run.mapIndex);
    getSupportChoices(run, state.profile);
  }
  // Dev only: unreleased engine cards in a Chain (default: the Chime loop). ?mock=engine, or
  // ?mock=cards&scenario=engine&chain=id,id,... A mock run like ?mock=cards: nothing is saved.
  if (params.get('scenario') === 'engine' || params.get('mock') === 'engine') {
    const ids = (params.get('chain') || 'first-catch,spark-chime,ember-bell,slow-wick').split(',').slice(0, 5);
    run.cardSlots = 5;
    run.companions = ['collector']; run.companionRole = 'collector';
    run.mountedCards = Array.from({ length: 5 }, (_, i) => ids[i] && ids[i] !== '-' ? makeSkillCard(ids[i].trim(), `sample:engine:${i}`) : null);
    run.reserveCards = (params.get('reserve') || 'metronome,heartbeat,crescendo,close-call,body-spark,overflow-bell,full-satchel,last-round,harvest-home,black-hole,echo,homing-thread,momentum,wave-loom,third-beat,long-fuse,low-ember,flash-tinder,afterglow')
      .split(',').map((id, i) => makeSkillCard(id.trim(), `sample:stored:engine:${i}`)).filter(Boolean);
  } else if (params.get('chain')) {
    // Dev only (captures): any Chain and reserve, ?mock=cards&chain=id,-,id&reserve=id,id
    const ids = params.get('chain').split(',').slice(0, 6);
    run.cardSlots = Math.max(3, ids.length);
    run.mountedCards = ids.map((id, i) => id && id !== '-' ? makeSkillCard(id.trim(), `sample:chain:${i}`) : null);
    if (params.get('reserve')) run.reserveCards = params.get('reserve').split(',').map((id, i) => makeSkillCard(id.trim(), `sample:stored:chain:${i}`)).filter(Boolean);
  }
  if (params.get('scenario') === 'starter') {
    delete run.startingGiftId;
    run.mountedCards = [null, null, null];
    run.reserveCards = [];
    delete run.cardReward;
    // ?gifts=id,id,id: the three offered starting cards (dev only; default is the seeded draw).
    if (params.get('gifts')) run.cardStarterOfferIds = params.get('gifts').split(',').map(id => id.trim()).slice(0, 3);
  }
  // Dev only: ?tallies=0:3,1:2 sets the count a growth card shows (slot:count).
  if (params.get('tallies')) for (const pair of params.get('tallies').split(',')) { const [i, n] = pair.split(':').map(Number); if (run.mountedCards[i]) run.mountedCards[i].tally = n; }
  // Dev only: ?mock=cards&chain=...&slots=0:gilded,2:hollow writes Inscriptions on slots (nothing is saved).
  if (params.get('slots')) applyInscriptionSlots(run, params.get('slots'));
  // Dev only: ?new=1 marks every reserve card and the first mounted card as unseen (shows the NEW badges; nothing is saved).
  if (params.get('new')) run.unseenCardIds = [...run.reserveCards, run.mountedCards.find(Boolean)].filter(Boolean).map(c => c.instanceId);
  // Dev only: ?mock=cards&scenario=scribe opens the Scribe after an Elite (offers=id,id,id; pick=id jumps to the slot step).
  if (params.get('scenario') === 'scribe') openMockScribe(run, params.get('offers'));
  // ?scenario=chest-write&gift=farLens: the slot screen for a chest gift (a permanent Inscription a chest writes).
  if (params.get('scenario') === 'chest-write') grantTreasureGift(run, params.get('gift') || 'farLens');
  return state;
}

/** The Scribe reward of an Elite flight, offering the given Inscriptions (default: one of each kind and a third). */
export function openMockScribe(run, offers) {
  const ids = String(offers || 'cinder,brimful').split(',').map(id => id.trim()).filter(id => INSCRIPTIONS[id]).slice(0, 2);
  if (run.cardReward) run.cardReward.uiAcknowledged = true;
  delete run.cardDraft;
  run.lastFlight = {...(run.lastFlight || {}), elite: true};
  run.flightReward = {kind: 'inscription', nodeId: 'mock-scribe', source: 'flight', sourceName: 'The Scribe', offers: ids, permanent: false, claimed: !ids.length};
  run.victoryPending = true;
  return run.flightReward;
}
/** `0:gilded,2:hollow` → Inscriptions on those slots; unknown ids and slots are ignored. */
export function applyInscriptionSlots(run, text) {
  cleanSlotInscriptions(run);
  for (const part of String(text || '').split(',')) {
    const [index, idText] = part.split(':');
    writeInscription(run, Number(index), (idText || '').trim());
  }
  return run.slotInscriptions;
}
